16	import { clsx } from "clsx";
17	
18	/* Types
19	  ============================================ */
20	
21	/* clsx
22	  ---------------------------------- */
23	
24	// When compiling with `declaration: true`, many projects experience the dreaded
25	// TS2742 error. To combat this, we copy clsx's types manually.
26	// Should this project move to JSDoc, this workaround would no longer be needed.
27	
28	export type ClassValue =
29	  | ClassArray
30	  | ClassDictionary
31	  | string
32	  | number
33	  | bigint
34	  | null
35	  | boolean
36	  | undefined;
37	export type ClassDictionary = Record<string, any>;
38	export type ClassArray = ClassValue[];
39	
40	/* Utils
41	  ---------------------------------- */
42	
43	type OmitUndefined<T> = T extends undefined ? never : T;
44	type StringToBoolean<T> = T extends "true" | "false" ? boolean : T;
45	type UnionToIntersection<U> = (U extends any ? (k: U) => void : never) extends (
46	  k: infer I,
47	) => void
48	  ? I
49	  : never;
50	
51	// `composes` accepts either a single component or a list of components. A
52	// plain union (`CVAComponentShape | CVAComponentShape[]`) collapses an array
53	// literal's element type to a union, silently dropping components whose
54	// variants are a structural subtype of another composed component's (e.g.
55	// `composes: [a, b]` where `b`'s variants are a superset of `a`'s). Splitting
56	// inference across two type parameters preserves the array as a real tuple.
57	type ComposedTuple<
58	  S extends CVAComponentShape | undefined,
59	  L extends readonly CVAComponentShape[],
60	> = [S] extends [CVAComponentShape] ? [S] : L;
61	
62	type MergedVariants<T extends readonly unknown[]> = UnionToIntersection<
63	  {
64	    [K in keyof T]: T[K] extends {
65	      config: { variants?: infer V extends CVAVariantShape };
66	    }
67	      ? V
68	      : never;
69	  }[number]
70	>;
71	
72	// Right-biased merge (`B`'s keys win on conflicts) implemented as a mapped
73	// type rather than `Omit<A, keyof B> & B`: the latter stays an unresolved
74	// deferred type when `A`/`B` are themselves generic (as they are here, via
75	// `ReturnType<CVA>` with no concrete `Config`), which then breaks downstream
76	// `any`-narrowing in unrelated code that consumes `ReturnType<CVA>` (e.g.
77	// the deprecated `compose`). A mapped type resolves eagerly instead.
78	type RightMerge<A, B> = {
79	  [K in keyof A | keyof B]: K extends keyof B
80	    ? B[K]
81	    : K extends keyof A
82	      ? A[K]
83	      : never;
84	};
85	
86	// `D` infers as `undefined` (not absent) when a component declares no
87	// `defaultVariants` at all. `NonNullable<undefined>` would give `never`,
88	// and `keyof never` is `string | number | symbol` (not `never`) — poisoning
89	// `RightMerge`'s key union with every possible key. Normalize to `{}` instead,
90	// matching a component that contributes nothing to the merge.
91	type DefaultsOf<Component> = Component extends {
92	  config: { defaultVariants?: infer D };
93	}
94	  ? D extends undefined
95	    ? {}
96	    : D
97	  : {};
98	
99	type MergedDefaultVariants<T extends readonly unknown[]> = T extends readonly [
100	  infer Head,
101	  ...infer Rest,
102	]
103	  ? RightMerge<DefaultsOf<Head>, MergedDefaultVariants<Rest>>
104	  : {};
105	
106	export type VariantProps<Component extends (...args: any) => any> = Omit<
107	  OmitUndefined<Parameters<Component>[0]>,
108	  "class" | "className"
109	>;
110	
111	/* compose
112	  ---------------------------------- */
113	
114	/**
115	 * @deprecated Use the `composes` property inside `cva` instead.
116	 * @example
117	 * // Before
118	 * const card = compose(box, stack)
119	 * // After
120	 * const card = cva({ composes: [box, stack] })
121	 */
122	export interface Compose {
123	  <T extends ReturnType<CVA>[]>(
124	    ...components: [...T]
125	  ): (
126	    props?: (
127	      | UnionToIntersection<
128	          {
129	            [K in keyof T]: VariantProps<T[K]>;
130	          }[number]
131	        >
132	      | undefined
133	    ) &
134	      CVAClassProp,
135	  ) => string;
136	}
137	
138	/* cx
139	  ---------------------------------- */
140	
141	export interface CX {
142	  (...inputs: ClassValue[]): string;
143	}
144	
145	export type CXOptions = Parameters<CX>;
146	export type CXReturn = ReturnType<CX>;
147	
148	/* cva
149	  ============================================ */
150	
151	type CVAComponentConfigBase = { base?: ClassValue };
152	/**
153	 * Exported so TypeScript can name this type in your generated declarations
154	 * (`declaration: true`) — you shouldn't really use it directly.
155	 */
156	export type CVAVariantShape = Record<string, Record<string, ClassValue>>;
157	type CVAVariantSchema<V extends CVAVariantShape> = {
158	  [Variant in keyof V]?: StringToBoolean<keyof V[Variant]> | undefined;
159	};
160	type CVAClassProp =
161	  | {
162	      class?: ClassValue;
163	      className?: never;
164	    }
165	  | {
166	      class?: never;
167	      className?: ClassValue;
168	    };
169	
170	type InternalOnlyWarning =
171	  "cva's generic parameters are restricted to internal use only.";
172	
173	type CVAComponentConfig<
174	  Config,
175	  Variants,
176	  ComposedSingle extends CVAComponentShape | undefined =
177	    | CVAComponentShape
178	    | undefined,
179	  ComposedList extends readonly CVAComponentShape[] =
180	    readonly CVAComponentShape[],
181	> = Config & {
182	  composes?: ComposedSingle | readonly [...ComposedList];
183	} & (Variants extends CVAVariantShape
184	    ? CVAComponentConfigBase & {
185	        variants?: Variants;
186	        compoundVariants?: (Variants extends CVAVariantShape
187	          ? (
188	              | CVAVariantSchema<Variants>
189	              | {
190	                  [Variant in keyof Variants]?:
191	                    | StringToBoolean<keyof Variants[Variant]>
192	                    | StringToBoolean<keyof Variants[Variant]>[]
193	                    | undefined;
194	                }
195	            ) &
196	              CVAClassProp
197	          : CVAClassProp)[];
198	        defaultVariants?: CVAVariantSchema<Variants>;
199	      }
200	    : CVAComponentConfigBase & {
201	        variants?: never;
202	        compoundVariants?: never;
203	        defaultVariants?: never;
204	      });
205	
206	/**
207	 * Exported so TypeScript can name this type in your generated declarations
208	 * (`declaration: true`) — you shouldn't really use it directly.
209	 */
210	export interface CVAComponent<Config, Variants> {
211	  (
212	    props?: Variants extends CVAVariantShape
213	      ? CVAVariantSchema<Variants> & CVAClassProp
214	      : CVAClassProp,
215	  ): string;
216	  /** @internal */
217	  config: Config;
218	}
219	
220	// The loosest form a composable component can take, constraining `composes`
221	// and the composition merge helpers above. Deriving it from `CVAComponent`
222	// keeps the two from drifting: instantiated with `any`, the props conditional
223	// and `config` both collapse to `any` (mapped types over `any` are `any`),
224	// i.e. `{ (props?: any): string; config: any }`. The required `config`
225	// property is what rejects plain functions and (deprecated) `compose`
226	// results.
227	//
228	// The `any` arguments are deliberate, not lazy typing — a shaped `config`
229	// (e.g. `{ variants?: CVAVariantShape }`) was tried and verifiably breaks:
230	// a variant-less `cva({ base })` carries `variants: unknown`, and
231	// `ReturnType<CVA>` instantiates this constraint inside the
232	// `Compose`/`GetSchema` guards, where the shaped form rejects every real
233	// component via props contravariance.
234	/**
235	 * Exported so TypeScript can name this type in your generated declarations
236	 * (`declaration: true`) — you shouldn't really use it directly.
237	 */
238	export type CVAComponentShape = CVAComponent<any, any>;
239	
240	type CVADefaultVariants<Config> = Config extends { defaultVariants?: infer D }
241	  ? D
242	  : {};
243	
244	export interface CVA {
245	  <
246	    _ extends InternalOnlyWarning,
247	    Config,
248	    Variants,
249	    ComposedSingle extends CVAComponentShape | undefined = undefined,
250	    ComposedList extends readonly CVAComponentShape[] = [],
251	  >(
252	    config: CVAComponentConfig<Config, Variants, ComposedSingle, ComposedList>,
253	  ): CVAComponent<
254	    Omit<Config, "defaultVariants"> & {
255	      variants: Variants &
256	        MergedVariants<ComposedTuple<ComposedSingle, ComposedList>>;
257	      // Local `defaultVariants` win over composed ones on key conflicts,
258	      // matching the runtime spread order. A plain intersection would collapse
259	      // a conflicting key's value to `never` (e.g. `"sm" & "lg"`), which then
260	      // silently drops the variant from `getSchema`'s inferred type.
261	      defaultVariants: Omit<
262	        MergedDefaultVariants<ComposedTuple<ComposedSingle, ComposedList>>,
263	        keyof CVADefaultVariants<Config>
264	      > &
265	        CVADefaultVariants<Config>;
266	    },
267	    Variants & MergedVariants<ComposedTuple<ComposedSingle, ComposedList>>
268	  >;
269	}
270	
271	/* defineConfig
272	  ---------------------------------- */
273	
274	export interface DefineConfigOptions {
275	  hooks?: {
276	    /**
277	     * @deprecated please use `onComplete`
278	     */
279	    "cx:done"?: (className: string) => string;
280	    /**
281	     * Returns the completed string of concatenated classes/classNames.
282	     */
283	    onComplete?: (className: string) => string;
284	  };
285	}
286	
287	export interface DefineConfig {
288	  (options?: DefineConfigOptions): {
289	    /**
290	     * @deprecated Use the `composes` property inside `cva` instead.
291	     * @example
292	     * // Before
293	     * const card = compose(box, stack)
294	     * // After
295	     * const card = cva({ composes: [box, stack] })
296	     */
297	    compose: Compose;
298	    cx: CX;
299	    cva: CVA;
300	  };
301	}
302	
303	/* Exports
304	  ============================================ */
305	
306	const falsyToString = <T extends unknown>(value: T) =>
307	  typeof value === "boolean" ? `${value}` : value === 0 ? "0" : value;
308	
309	// Shared across every non-composed call, rather than allocating a fresh `[]`
310	// per call — `cx` (clsx) treats an empty array identically to an absent one.
311	const emptyClassNames: string[] = [];
312	
313	export const defineConfig: DefineConfig = (options) => {
314	  const cx: CX = (...inputs) => {
315	    if (typeof options?.hooks?.["cx:done"] !== "undefined")
316	      return options?.hooks["cx:done"](clsx(inputs));
317	
318	    if (typeof options?.hooks?.onComplete !== "undefined")
319	      return options?.hooks.onComplete(clsx(inputs));
320	
321	    return clsx(inputs);
322	  };
323	
324	  const cva = (<
325	    _ extends InternalOnlyWarning,
326	    Config,
327	    Variants,
328	    ComposedSingle extends CVAComponentShape | undefined = undefined,
329	    ComposedList extends readonly CVAComponentShape[] = [],
330	  >(
331	    config: CVAComponentConfig<Config, Variants, ComposedSingle, ComposedList>,
332	  ) => {
333	    const components = (
334	      config?.composes == null
335	        ? []
336	        : Array.isArray(config.composes)
337	          ? config.composes
338	          : [config.composes]
339	    ) as CVAComponentShape[];
340	    // A one-level-deep merge per variant key, so overlapping variants (e.g.
341	    // multiple composed components declaring `style`) union their values
342	    // instead of the last component's values silently replacing the rest.
343	    const mergeVariants = (
344	      acc: CVAVariantShape,
345	      variants: CVAVariantShape | undefined,
346	    ): CVAVariantShape => {
347	      if (!variants) return acc;
348	      const merged: CVAVariantShape = { ...acc };
349	      for (const key of Object.keys(variants)) {
350	        merged[key] = { ...merged[key], ...variants[key] };
351	      }
352	      return merged;
353	    };
354	    const mergedVariantsFromComposed = components.reduce(
355	      (acc: CVAVariantShape, component: CVAComponentShape) =>
356	        mergeVariants(acc, component.config?.variants),
357	      {} as CVAVariantShape,
358	    );
359	    const mergedVariants = mergeVariants(
360	      mergedVariantsFromComposed,
361	      config?.variants as CVAVariantShape | undefined,
362	    );
363	    const mergedDefaultVariantsFromComposed = components.reduce(
364	      (acc: Record<string, unknown>, component: CVAComponentShape) => ({
365	        ...acc,
366	        ...component.config?.defaultVariants,
367	      }),
368	      {} as Record<string, unknown>,
369	    );
370	    // Local `defaultVariants` win over composed ones here too (last spread).
371	    const mergedDefaultVariants: Record<string, unknown> = {
372	      ...mergedDefaultVariantsFromComposed,
373	      ...config?.defaultVariants,
374	    };
375	
376	    const component: CVAComponent<typeof config, typeof config.variants> = (
377	      props,
378	    ) => {
379	      // Strip `class`/`className` and explicit `undefined` from props once,
380	      // reused for both the composed-component calls and compound-variant
381	      // matching. An explicit `{ variant: undefined }` is dropped so it falls
382	      // back to the (possibly composed) default, matching variant resolution
383	      // below. Only built when something consumes it — a plain component with
384	      // no `composes` and no `variants` skips the work entirely.
385	      const definedPropsWithoutClass =
386	        components.length || config?.variants != null
387	          ? Object.fromEntries(
388	              Object.entries(props || {}).filter(
389	                ([key, value]) =>
390	                  key !== "class" &&
391	                  key !== "className" &&
392	                  typeof value !== "undefined",
393	              ),
394	            )
395	          : {};
396	
397	      const getComposedClassNames = components.length
398	        ? components.map((component: CVAComponentShape) =>
399	            component({
400	              ...mergedDefaultVariants,
401	              ...definedPropsWithoutClass,
402	            }),
403	          )
404	        : emptyClassNames;
405	
406	      if (config?.variants == null) {
407	        return cx(
408	          getComposedClassNames,
409	          config?.base,
410	          props?.class,
411	          props?.className,
412	        );
413	      }
414	
415	      const { variants } = config;
416	
417	      // Resolve against the *merged* defaults (composed + local) so a variant
418	      // redeclared locally over a composed key uses the same effective default
419	      // the composed components and `getSchema` see.
420	      const getVariantClassNames = Object.keys(variants).map(
421	        (variant: keyof typeof variants) => {
422	          const variantProp = props?.[variant as keyof typeof props];
423	          const defaultVariantProp = mergedDefaultVariants[variant as string];
424	
425	          const variantKey = (falsyToString(variantProp) ||
426	            falsyToString(
427	              defaultVariantProp,
428	            )) as keyof (typeof variants)[typeof variant];
429	
430	          return variants[variant][variantKey];
431	        },
432	      );
433	
434	      const defaultsAndProps = {
435	        ...mergedDefaultVariants,
436	        ...definedPropsWithoutClass,
437	      };
438	
439	      const getCompoundVariantClassNames = config?.compoundVariants?.reduce(
440	        (
441	          acc: ClassValue[],
442	          {
443	            class: cvClass,
444	            className: cvClassName,
445	            ...cvConfig
446	          }: CVAClassProp & Record<string, unknown>,
447	        ) =>
448	          Object.entries(cvConfig).every(([cvKey, cvSelector]) => {
449	            const selector =
450	              defaultsAndProps[cvKey as keyof typeof defaultsAndProps];
451	
452	            return Array.isArray(cvSelector)
453	              ? cvSelector.includes(selector)
454	              : selector === cvSelector;
455	          })
456	            ? [...acc, cvClass, cvClassName]
457	            : acc,
458	        [] as ClassValue[],
459	      );
460	
461	      return cx(
462	        getComposedClassNames,
463	        config?.base,
464	        getVariantClassNames,
465	        getCompoundVariantClassNames,
466	        props?.class,
467	        props?.className,
468	      );
469	    };
470	
471	    component.config = {
472	      ...config,
473	      variants: mergedVariants,
474	      defaultVariants: mergedDefaultVariants,
475	    };
476	
477	    return component as ReturnType<CVA>;
478	  }) as CVA;
479	
480	  const compose: Compose = (...components) => {
481	    const config = components.reduce(
482	      (acc, { config }) => {
483	        Object.entries(config || {}).forEach(([key, value]) => {
484	          acc[key] =
485	            typeof value === "object" && value !== null && !Array.isArray(value)
486	              ? {
487	                  ...acc[key],
488	                  ...value,
489	                }
490	              : value;
491	        });
492	        return acc;
493	      },
494	      // A loose accumulator: composed configs carry heterogeneous values
495	      // (base strings, variant maps, compoundVariant arrays), not just the
496	      // `CVAVariantShape` the merged `variants` key holds.
497	      {} as Record<string, any>,
498	    );
499	
500	    const component: CVAComponent<typeof config, typeof config.variants> = (
501	      props,
502	    ) => {
503	      const propsWithoutClass = Object.fromEntries(
504	        Object.entries(props || {}).filter(
505	          ([key]) => !["class", "className"].includes(key),
506	        ),
507	      );
508	
509	      return cx(
510	        components.map((component) => component(propsWithoutClass)),
511	        props?.class,
512	        props?.className,
513	      );
514	    };
515	
516	    component.config = config;
517	
518	    return component;
519	  };
520	
521	  return {
522	    compose,
523	    cva,
524	    cx,
525	  };
526	};
527	
528	export const { compose, cva, cx } = defineConfig();
529	
530	export interface GetSchema {
531	  <_ extends InternalOnlyWarning, Component, Config, Variants>(
532	    component: Component &
533	      (Component extends ReturnType<CVA>
534	        ? { config: CVAComponentConfig<Config, Variants> }
535	        : never),
536	  ): {
537	    [Variant in keyof Variants]: Config extends CVAComponentConfig<
538	      Config,
539	      Variants
540	    >
541	      ? Variant extends keyof Config["defaultVariants"]
542	        ? Config["defaultVariants"][Variant] extends undefined
543	          ? never
544	          : {
545	              values: ReadonlyArray<StringToBoolean<keyof Variants[Variant]>>;
546	              defaultValue: Readonly<
547	                StringToBoolean<Config["defaultVariants"][Variant]>
548	              >;
549	            }
550	        : {
551	            values: ReadonlyArray<StringToBoolean<keyof Variants[Variant]>>;
552	          }
553	      : never;
554	    // Iterate over the returned schema and remove any keys that have no values
555	  } extends infer Schema
556	    ? {
557	        [K in keyof Schema as Schema[K] extends {
558	          values: readonly never[];
559	        }
560	          ? never
561	          : K]: Schema[K] extends { defaultValue: never } ? never : Schema[K];
562	      }
563	    : never;
564	}
565	
566	export const getSchema: GetSchema = (component) => {
567	  if (!component.config?.variants) return {} as any;
568	
569	  return Object.entries(component.config.variants).reduce(
570	    (acc, [key, value]) => {
571	      const defaultValue = component.config.defaultVariants?.[key];
572	      const hasDefaultValue = defaultValue !== undefined;
573	      const values = Object.keys(value).map((v) => {
574	        if (v === "true") return true;
575	        if (v === "false") return false;
576	        // Normalize numeric-literal keys back to numbers, since that's how
577	        // they appear in variant prop types (`keyof { 1: ... }` is `1`, not
578	        // `"1"`) — object keys are always strings/symbols at runtime. The
579	        // `String(n) === v` round-trip only accepts canonical numeric forms
580	        // (so `"01"`, `""`, `" 1"` stay strings), covering negatives too.
581	        const n = Number(v);
582	        return Number.isFinite(n) && String(n) === v ? n : v;
583	      }) as StringToBoolean<keyof typeof value>[];
584	      const hasValues = values.length > 0;
585	
586	      return hasValues || hasDefaultValue
587	        ? {
588	            ...acc,
589	            [key]: {
590	              ...(hasValues ? { values } : {}),
